      +'<td>'+person(r[2],r[3])+'</td>'                 // JMS Sales VP
      +'<td>'+person(r[4],r[5])+'</td>'                 // JMS Sales Director
      +'<td>'+person(r[6],r[7])+'</td>'                 // JMS Sales Manager
      +'<td style="font-size:12px">'+esc(r[8])+'</td>'  // Acosta Leadership
