      +'<td style="font-size:12px">'+esc(r[11])+'</td>' // Centralized Trade Specialist
      +'<td style="font-size:12px">'+esc(r[12])+'</td>' // Local Trade Specialist
      +'<td style="font-size:12px">'+esc(r[13])+'</td>' // Local Trade Manager
