function renderNatDist(rows){
  var b=document.getElementById("n-body"),h="";
  if(!rows.length){b.innerHTML='<tr><td colspan="7" class="empty">No results</td></tr>';document.getElementById("n-count").textContent="0 rows";return;}
  for(var i=0;i<rows.length;i++){var r=rows[i];h+='<tr><td style="color:#9ab4cc;font-size:12px">'+(i+1)+'</td><td><strong>'+esc(r[0])+'</strong></td><td>'+esc(r[1])+'</td><td>'+person(r[2],r[3])+'</td><td>'+sba(r[4])+'</td><td>'+person(r[5],r[6])+'</td><td>'+esc(r[7])+'</td></tr>';}
  b.innerHTML=h;document.getElementById("n-count").textContent=rows.length+" rows";
}
function renderRC(items){
  var b=document.getElementById("rc-body"),h="";
  if(!items.length){b.innerHTML='<tr><td colspan="4" class="empty">No results</td></tr>';document.getElementById("rc-count").textContent="0 codes";return;}
  for(var i=0;i<items.length;i++){
    var r=items[i];
    var rl=REPAY_LETTERS.hasOwnProperty(r.code.toUpperCase())?REPAY_LETTERS[r.code.toUpperCase()]:undefined;
    var btn=rl
      ?'<a href="'+esc(rl)+'" target="_blank" style="display:inline-block;padding:4px 10px;background:#1c2b3a;color:#fff;border-radius:4px;font-size:11px;font-weight:500;text-decoration:none;white-space:nowrap">ðŸ“¬ Open</a>'
      :(rl===null?'<span style="font-size:11px;color:#9ab4cc;font-style:italic">Not Available</span>':'<span style="font-size:11px;color:#9ab4cc">—</span>');
    h+='<tr><td class="rc-name-cell">'+esc(r.code)+'</td><td>'+esc(r.desc)+'</td><td class="rc-q-cell">'+esc(r.q)+'</td><td>'+btn+'</td></tr>';
  }
  b.innerHTML=h;document.getElementById("rc-count").textContent=items.length+" codes";
}
function renderPortals(items){
  var g=document.getElementById("portal-grid"),h="";
  var statusMap={active:"status-active",info:"status-info",warn:"status-warn"};
  var statusLabel={active:"Active",info:"Info Only",warn:"Not Available"};
  if(!items.length){g.innerHTML='<div class="empty" style="grid-column:1/-1">No portals found.</div>';document.getElementById("portal-count").textContent="";return;}
  for(var i=0;i<items.length;i++){
    var p=items[i];
    var sc=statusMap[p.status]||"status-info";
    var sl=statusLabel[p.status]||p.status;
    if(p.url){
      h+='<a class="portal-card" href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">'
        +'<h4>'+esc(p.name)+'</h4>'
        +'<p>'+esc(p.desc)+'</p>'
        +'<div class="portal-card-footer"><span class="status-pill '+sc+'">'+sl+'</span><span class="portal-arrow">&#x2197;</span></div>'
        +'</a>';
    } else {
      h+='<div class="portal-card" style="cursor:default;opacity:.7">'
        +'<h4>'+esc(p.name)+'</h4>'
        +'<p>'+esc(p.desc)+'</p>'
        +'<div class="portal-card-footer"><span class="status-pill '+sc+'">'+sl+'</span></div>'
        +'</div>';
    }
  }
  g.innerHTML=h;
  document.getElementById("portal-count").textContent=items.length+" portals";
}

