function lbGetFields() {
  return {
    TO: (document.getElementById("lb-to").value.trim() || "[Recipient Name]"),
    COMPANY: (document.getElementById("lb-company").value.trim() || "[Company]"),
    CLAIM: (document.getElementById("lb-claim").value.trim() || "[Claim #]"),
    AMOUNT: (document.getElementById("lb-amount").value.trim() || "[Amount]"),
    CUSTOMER: (document.getElementById("lb-customer").value.trim() || "[Customer]"),
    FROM: (document.getElementById("lb-from").value.trim() || "[Your Name]")
  };
}

function lbFill(tpl, fields) {
  return tpl
    .replace(/{TO}/g, fields.TO)
    .replace(/{COMPANY}/g, fields.COMPANY)
    .replace(/{CLAIM}/g, fields.CLAIM)
    .replace(/{AMOUNT}/g, fields.AMOUNT)
    .replace(/{CUSTOMER}/g, fields.CUSTOMER)
    .replace(/{FROM}/g, fields.FROM);
}

function lbSelectCard(el, type) {
  // Highlight selected card
  document.querySelectorAll(".lb-type-card").forEach(function(c){ c.classList.remove("selected"); });
  el.classList.add("selected");
  document.getElementById("lb-type").value = type;
  // Show editor area, hide empty state
  document.getElementById("lb-empty-state").style.display = "none";
  document.getElementById("lb-editor-area").style.display = "block";
  if (type === "freeform") {
    document.getElementById("lb-editor").value = "";
    document.getElementById("lb-editor").placeholder = "Write your letter here…";
    document.getElementById("lb-copilot-out").innerHTML = '<div class="cop-item" style="color:#9ab4cc;font-style:italic">Start typing — Copilot will review your letter as you write.</div>';
    return;
  }
  var tpl = LB_TEMPLATES[type];
  if (!tpl) return;
  var fields = lbGetFields();
  document.getElementById("lb-editor").value = lbFill(tpl, fields);
  lbCopilotAnalyze();
}

function lbLoadTemplate() {
  var type = document.getElementById("lb-type").value;
  if (!type) return;
  var tpl = LB_TEMPLATES[type];
  if (tpl === undefined) return;
  if (type === "freeform") {
    document.getElementById("lb-editor").value = "";
    return;
  }
  var fields = lbGetFields();
  document.getElementById("lb-editor").value = lbFill(tpl, fields);
  lbCopilotAnalyze();
}

function lbUpdatePreview() {
  /* re-render the letter preview using current field values */
  var type = document.getElementById("lb-type").value;
  if (!type || type === "freeform") return;
  var tpl = LB_TEMPLATES[type];
  if (!tpl) return;
  var fields = lbGetFields();
  document.getElementById("lb-editor").value = lbFill(tpl, fields);
  document.getElementById("lb-dl-hint").textContent = "";
  lbCopilotAnalyze();
}

function lbCopilotAnalyze() {
  var text = document.getElementById("lb-editor").value.trim();
  var out = document.getElementById("lb-copilot-out");
  if (!text || text.length < 20) {
    out.innerHTML = '<div class="cop-item" style="color:#9ab4cc;font-style:italic">Start typing or select a template — Copilot will review your letter here.</div>';
    return;
  }
  var items = [];

  // Tone check
  var lower = text.toLowerCase();
  if (lower.indexOf("kindly") >= 0 || lower.indexOf("respectfully") >= 0 || lower.indexOf("please") >= 0)
    items.push('<div class="cop-item"><span class="cop-good">Tone</span> — Professional and courteous tone detected.</div>');
  else
    items.push('<div class="cop-item"><span class="cop-warn">Tone</span> — Consider adding polite phrases like "please" or "kindly" to keep a professional tone.</div>');

  // Placeholder check
  var placeholders = text.match(/\[.*?\]/g);
  if (placeholders && placeholders.length > 0)
    items.push('<div class="cop-item"><span class="cop-warn">Placeholders</span> — Unfilled fields detected: <span class="cop-fix">' + placeholders.join(", ") + '</span>. Fill them in Step 2.</div>');
  else
    items.push('<div class="cop-item"><span class="cop-good">Fields</span> — All fields appear filled in.</div>');

  // Greeting check
  if (!/^dear\s/i.test(text))
    items.push('<div class="cop-item"><span class="cop-warn">Greeting</span> — Letter does not start with "Dear [Name]". Consider adding a proper salutation.</div>');
  else
    items.push('<div class="cop-item"><span class="cop-good">Greeting</span> — Salutation present.</div>');

  // Closing check
  if (/(sincerely|best regards|thank you|regards)/i.test(text))
    items.push('<div class="cop-item"><span class="cop-good">Closing</span> — Professional closing statement detected.</div>');
  else
    items.push('<div class="cop-item"><span class="cop-warn">Closing</span> — No closing statement found. Consider ending with "Sincerely," or "Best regards,".</div>');

  // Claim number check
  if (text.indexOf("[Claim #]") >= 0 || (!(/ded-|claim #|deduction #|inv-/i.test(text)) && text.toLowerCase().indexOf("claim") >= 0))
    items.push('<div class="cop-item"><span class="cop-warn">Claim Reference</span> — Confirm the deduction/claim number is included and correct.</div>');

  // Amount check
  if (text.indexOf("[Amount]") >= 0 || !(/\$[\d,]+/i.test(text)))
    items.push('<div class="cop-item"><span class="cop-warn">Amount</span> — No dollar amount detected. Ensure the repay amount is clearly stated.</div>');
  else
    items.push('<div class="cop-item"><span class="cop-good">Amount</span> — Dollar amount found in letter.</div>');

  // Profanity / inappropriate language check
  var profanityList = [
    "fuck","shit","ass","bitch","damn","crap","hell","bastard","cunt","piss",
    "dick","cock","pussy","asshole","bullshit","motherfucker","wtf","stfu","idiot",
    "moron","stupid","dumb","hate","kill","loser","jerk","retard","jackass"
  ];
  var foundProfanity = [];
  var words = lower.replace(/[^a-z\s]/g," ").split(/\s+/);
  words.forEach(function(w){
    if(profanityList.indexOf(w) >= 0 && foundProfanity.indexOf(w) < 0) foundProfanity.push(w);
  });
  if(foundProfanity.length > 0) {
    items.push('<div class="cop-item" style="background:#fff1f2;border-left:3px solid #e11d48;padding:8px 10px;border-radius:4px"><span style="color:#e11d48;font-weight:700">Inappropriate Language</span> — This letter contains language that is <strong>not suitable for professional correspondence</strong>. Please remove or replace: <span style="color:#e11d48;font-weight:600">' + foundProfanity.join(", ") + '</span>. This letter should not be sent as-is.</div>');
  } else {
    items.push('<div class="cop-item"><span class="cop-good">Language</span> — No inappropriate language detected. Letter is suitable for professional use.</div>');
  }

  // Word count
  var wc = text.split(/\s+/).filter(function(w){return w.length>0;}).length;
  items.push('<div class="cop-item" style="color:#9ab4cc">Word count: <strong>' + wc + '</strong> words.</div>');

  out.innerHTML = items.join("");
}

function lbDownload() {
  var text = document.getElementById("lb-editor").value.trim();
  var hint = document.getElementById("lb-dl-hint");
  if (!text) {
    hint.textContent = "Nothing to download — select a template first.";
    hint.style.color = "#92400e";
    return;
  }
  var customer = document.getElementById("lb-customer").value.trim() || "Letter";
  var type = (document.getElementById("lb-type").value.replace(/^repay_/,"") || "custom").replace(/_/g," ");
  var filename = "repay_" + (document.getElementById("lb-type").value.replace(/^repay_/,"") || "custom") + "_" + customer.replace(/[^a-z0-9]/gi,"_") + ".pdf";

  /* sanitize text for jsPDF helvetica (no em-dash, smart quotes, etc.) */
  function pdfSafe(s){ return s.replace(/\u2014/g,"--").replace(/\u2013/g,"-").replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/\u00B7/g,"-"); }

  if (!window.jspdf) {
    hint.textContent = "PDF library not loaded yet - please refresh the page and try again.";
    hint.style.color = "#92400e";
    return;
  }

  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({ unit:"pt", format:"letter" });

  /* ── header bar ── */
  doc.setFillColor(28, 43, 58);
  doc.rect(0, 0, 612, 52, "F");
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16);
  doc.setFont("helvetica","bold");
  doc.text("J.M. Smucker Company", 36, 33);
  doc.setFontSize(9);
  doc.setFont("helvetica","normal");
  doc.setTextColor(154, 180, 204);
  doc.text("Acosta Sales & Marketing  -  Repay Management", 36, 46);

  /* ── meta line ── */
  doc.setFontSize(9);
  doc.setTextColor(87, 96, 106);
  var today = new Date();
  var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  doc.text("Type: Repay Request - " + type.charAt(0).toUpperCase() + type.slice(1) +
           "     Customer: " + pdfSafe(document.getElementById("lb-customer").value.trim() || "-") +
           "     Date: " + months[today.getMonth()] + " " + today.getDate() + ", " + today.getFullYear(),
           36, 74);

  /* ── divider ── */
  doc.setDrawColor(229, 231, 235);
  doc.line(36, 80, 576, 80);

  /* ── body text ── */
  doc.setFontSize(11);
  doc.setTextColor(31, 35, 40);
  doc.setFont("helvetica","normal");
  var safeText = pdfSafe(text);
  var lines = doc.splitTextToSize(safeText, 504);
  doc.text(lines, 54, 104);

  /* ── footer ── */
  var pageHeight = doc.internal.pageSize.height;
  doc.setDrawColor(229, 231, 235);
  doc.line(36, pageHeight - 36, 576, pageHeight - 36);
  doc.setFontSize(8);
  doc.setTextColor(154, 180, 204);
  doc.text("J.M. Smucker Company  -  Acosta Sales & Marketing  -  Repay Management  -  Confidential", 36, pageHeight - 20);

  doc.save(filename);
  hint.textContent = "Downloaded: " + filename;
  hint.style.color = "#065f46";
}

function lbCopyClipboard() {
  var text = document.getElementById("lb-editor").value.trim();
  var hint = document.getElementById("lb-dl-hint");
  if (!text) {
    hint.textContent = "Nothing to copy — select a template first.";
    hint.style.color = "#92400e";
    return;
  }
  try {
    navigator.clipboard.writeText(text).then(function(){
      hint.textContent = "Copied to clipboard!";
      hint.style.color = "#065f46";
    });
  } catch(e) {
    // fallback
    var ta = document.createElement("textarea");
    ta.value = text;
    document.body.appendChild(ta);
    ta.select();
    document.execCommand("copy");
    document.body.removeChild(ta);
    hint.textContent = "Copied to clipboard!";
    hint.style.color = "#065f46";
  }
}

