// -- BPS RENDER & FILTER -------------------------------------------------------
function bpsTypePill(t){
  if(!t)return"";
  var tl=t.toLowerCase();
  if(tl.indexOf("wholesale")>=0||tl.indexOf("distributor")>=0)return'<span class="bps-pill-wholesale">'+esc(t)+'</span>';
  if(tl.indexOf("indirect")>=0)return'<span class="bps-pill-indirect">'+esc(t)+'</span>';
  return'<span class="bps-pill-direct">'+esc(t)+'</span>';
}
function bpsPortalPill(p){
  return(p==="yes")?'<span class="bps-pill-yes">âœ“ Portal</span>':'<span class="bps-pill-no">No Portal</span>';
}
function bpsSignOns(s){
  if(!s)return"";
  return s.split(/[·,]/).map(function(x){
    var t=x.trim();
    return t?'<span class="bps-signon">'+esc(t)+'</span>':'';
  }).filter(Boolean).join(" ");
}
function renderBPS(rows){
  var b=document.getElementById("bps-body");
  if(!b)return;
  if(!rows||!rows.length){b.innerHTML='<tr><td colspan="8" class="empty">No results</td></tr>';document.getElementById("bps-count").textContent="0 customers";return;}
  var h="";
  for(var i=0;i<rows.length;i++){
    var r=rows[i];
    h+='<tr>'
      +'<td style="color:#9ab4cc;font-size:11px;text-align:center">'+(i+1)+'</td>'
      +'<td><strong>'+esc(r[0])+'</strong></td>'
      +'<td>'+bpsTypePill(r[1])+'</td>'
      +'<td style="color:#1f2328">'+esc(r[2])+'</td>'
      +'<td>'+bpsPortalPill(r[3])+'</td>'
      +'<td style="color:#57606a">'+esc(r[4])+'</td>'
      +'<td style="color:#57606a">'+esc(r[5])+'</td>'
      +'</tr>';
  }
  b.innerHTML=h;
  document.getElementById("bps-count").textContent=rows.length+" customer"+(rows.length!==1?"s":"");
}
function bpsFilter(){
  var q=(document.getElementById("bps-search").value||"").toLowerCase();
  var typ=(document.getElementById("bps-type").value||"").toLowerCase();
  var por=(document.getElementById("bps-portal").value||"").toLowerCase();
  var filtered=BPS_DATA.filter(function(r){
    var matchQ=!q||r.join(" ").toLowerCase().indexOf(q)>=0;
    var matchTyp=!typ||r[1].toLowerCase().indexOf(typ)>=0;
    var matchPor=!por||(por==="yes"?r[3]==="yes":r[3]!=="yes");
    return matchQ&&matchTyp&&matchPor;
  });
  renderBPS(filtered);
}

renderBPS(BPS_DATA);

